<x-app-layout><div class="mb-6"><a href="{{ route('appointments.index') }}" class="text-sm text-slate-500">← Appointments</a><h1 class="mt-2 text-3xl font-black">{{ $appointment->exists?'Reschedule appointment':'New appointment' }}</h1><p class="text-slate-500">End time is calculated automatically from the selected service.</p></div><form method="POST" action="{{ $appointment->exists?route('appointments.update',$appointment):route('appointments.store') }}" class="card max-w-3xl p-6" x-data="{duration:{{ old('service_id',$appointment->service_id)?($services->firstWhere('id',old('service_id',$appointment->service_id))?->duration_minutes??0):0 }},start:'{{ old('start_time',$appointment->start_time?substr($appointment->start_time,0,5):'') }}',end(){if(!this.start||!this.duration)return '—';let [h,m]=this.start.split(':').map(Number);let t=h*60+m+Number(this.duration);return String(Math.floor(t/60)%24).padStart(2,'0')+':'+String(t%60).padStart(2,'0')}}">@csrf @if($appointment->exists)@method('PUT')@endif<div class="grid gap-5 sm:grid-cols-2"><div class="sm:col-span-2"><label class="form-label">Customer *</label><select class="form-input" name="customer_id" required><option value="">Select customer</option>@foreach($customers as $c)<option value="{{ $c->id }}" @selected(old('customer_id',$appointment->customer_id)==$c->id)>{{ $c->full_name }} · {{ $c->contact_number }}</option>@endforeach</select></div><div><label class="form-label">Barber *</label><select class="form-input" name="barber_id" required><option value="">Select barber</option>@foreach($barbers as $b)<option value="{{ $b->id }}" @selected(old('barber_id',$appointment->barber_id)==$b->id)>{{ $b->full_name }} · {{ $b->specialization }}</option>@endforeach</select></div><div><label class="form-label">Service *</label><select class="form-input" name="service_id" @change="duration=$event.target.selectedOptions[0].dataset.duration" required><option value="" data-duration="0">Select service</option>@foreach($services as $s)<option data-duration="{{ $s->duration_minutes }}" value="{{ $s->id }}" @selected(old('service_id',$appointment->service_id)==$s->id)>{{ $s->name }} · ₱{{ number_format($s->price,2) }} · {{ $s->duration_minutes }} min</option>@endforeach</select></div><div><label class="form-label">Appointment date *</label><input type="date" min="{{ now()->toDateString() }}" class="form-input" name="appointment_date" value="{{ old('appointment_date',$appointment->appointment_date?->format('Y-m-d')) }}" required></div><div><label class="form-label">Start time *</label><input type="time" class="form-input" name="start_time" x-model="start" value="{{ old('start_time',$appointment->start_time?substr($appointment->start_time,0,5):'') }}" required><p class="mt-2 text-xs text-slate-500">Estimated end: <b x-text="end()"></b></p></div><div><label class="form-label">Status *</label><select class="form-input" name="status">@foreach(\App\Models\Appointment::STATUSES as $s)<option value="{{ $s }}" @selected(old('status',$appointment->status?:'pending')===$s)>{{ ucwords(str_replace('_',' ',$s)) }}</option>@endforeach</select></div><div class="sm:col-span-2"><label class="form-label">Notes</label><textarea class="form-input" rows="3" name="notes">{{ old('notes',$appointment->notes) }}</textarea></div></div><div class="mt-6 flex gap-3"><button class="btn-primary">{{ $appointment->exists?'Save changes':'Schedule appointment' }}</button><a class="btn-secondary" href="{{ route('appointments.index') }}">Cancel</a></div></form></x-app-layout>
